run:
set -uo pipefail
cmd={{command}}
[ -n "$cmd" ] || cmd={{fallback}}
if [ -z "$cmd" ]; then echo "no test command; give one when starting the run" >&2; exit 1; fi
echo "\$ $cmd"
bash -c "$cmd" 2>&1 | tail -40
status=${PIPESTATUS[0]}
[ "$status" -eq 0 ] && echo "tests passed" || { echo "tests failed (exit $status)" >&2; exit "$status"; }
